-- PrayerLock seed: 100 predefined quests (20 per pillar) + badge catalog.
-- Idempotent: safe to run on every `supabase db reset`.

----------------------------------------------------------------------
-- BADGE CATALOG
----------------------------------------------------------------------
insert into public.badge_catalog (badge_id, name, description, rarity, xp_reward, pillar, sort) values
  ('first_step',      'First Step',       'Complete your very first quest.',                          'common',    50,   null,           1),
  ('social_spark',    'Social Spark',     'Add your first friend.',                                   'common',    50,   null,           2),
  ('week_warrior',    'Week Warrior',     'Hold a 7-day streak.',                                     'uncommon',  200,  null,           3),
  ('perfect_day',     'Perfect Day',      'Reach a 100% Daily Life Score.',                           'uncommon',  150,  null,           4),
  ('early_riser',     'Early Riser',      'Complete a quest before 8 AM, 7 days in a row.',           'uncommon',  150,  null,           5),
  ('comeback',        'Comeback',         'Complete 5 quests the day after a zero day.',              'uncommon',  150,  null,           6),
  ('ten_day_streak',  'Unstoppable',      'Hold a 10-day streak.',                                    'uncommon',  250,  null,           7),
  ('prayer_master',   'Prayer Master',    'Complete 30 spirituality quests in one month.',            'rare',      500,  'spirituality', 8),
  ('fitness_fanatic', 'Fitness Fanatic',  'Complete 50 workout quests in one month.',                 'rare',      400,  'health',       9),
  ('family_first',    'Family First',     'Weekly parents call, 8 weeks in a row.',                   'rare',      350,  'family',       10),
  ('adventurer',      'Adventurer',       'Complete 20 different fun quests.',                        'rare',      400,  'fun',          11),
  ('knowledge_seeker','Knowledge Seeker', 'Bank 100 hours of deep work.',                             'epic',      1000, 'work',         12),
  ('month_master',    'Month Master',     'Hold a 30-day streak.',                                    'epic',      1000, null,           13),
  ('iron_mind',       'Iron Mind',        'Reach level 50.',                                          'epic',      2000, null,           14),
  ('legend',          'Legend',           'Reach level 100.',                                         'legendary', 5000, null,           15)
on conflict (badge_id) do nothing;

